// The Wider Canopy — every tree species on the Morpeace property.
//
// Counts and CO₂e come from the tgctree census (treeCensus.ts, generated by
// scripts/trees-to-census.py from the CSV export). The April 2026 baseline
// (447 trees) grew to the full April–October 2026 census, which also includes
// the Nakshatra Van saplings planted in July 2026.
//
// This file holds only names, origin and categories. Classification
// (native / introduced) follows the baseline report's rule-based framework.
// Sentinel species with stories carry `sentinelTreeTag` — clicking the tile
// opens /the-forest/:treeTag for the full chapter-based poem.

import { treeCensus } from './treeCensus'

export type SpeciesCategory =
  | 'sacred'
  | 'fruiting'
  | 'native-forest'
  | 'flowering'
  | 'timber'
  | 'palm'
  | 'medicinal'
  | 'ornamental'

export type Origin = 'native' | 'exotic' | 'unclassified'

export interface Species {
  id: string
  common: string
  scientific: string
  marathi?: string
  count: number
  totalCo2eKg: number
  origin: Origin
  categories: SpeciesCategory[]
  sentinelTreeTag?: string
  iucn?: 'VU' | 'EN' | 'CR' // IUCN Red List status where applicable
  note?: string
}

type SpeciesMeta = Omit<Species, 'count' | 'totalCo2eKg'>

