const census: Record<string, { count: number; co2eKg: number }> = treeCensus.bySpecies

export const species: Species[] = speciesMeta.map((m) => ({
  ...m,
  count: census[m.id]?.count ?? (m.sentinelTreeTag ? 1 : 0),
  totalCo2eKg: census[m.id]?.co2eKg ?? 0,
}))

export const speciesByOrigin: Record<Origin, Species[]> = {
  native: [],
  exotic: [],
  unclassified: [],
}

species.forEach((s) => speciesByOrigin[s.origin].push(s))

// Leaderboard: the 15 most common identified species.
export const topSpecies = species
  .filter((s) => s.id !== 'other')
  .sort((a, b) => b.count - a.count)
  .slice(0, 15)

// The "all species" list for the full census view, sorted by count descending then name.
export const allSpecies = species
  .filter((s) => s.count > 0)
  .slice()
  .sort((a, b) => (b.count - a.count) || a.common.localeCompare(b.common))

// ---------- Aggregate stats (census only; story trees outside it are left out) ----------

const inCensus = (o: Origin) =>
  speciesByOrigin[o].reduce((sum, s) => sum + (census[s.id]?.count ?? 0), 0)
const nativeCount = inCensus('native')
const exoticCount = inCensus('exotic')
const unclassifiedCount = inCensus('unclassified')
const totalCounted = nativeCount + exoticCount + unclassifiedCount
const sandalwood = census['santalum-album']?.count ?? 0

export const speciesStats = {
  totalTrees: treeCensus.totalTrees,
  totalSpecies: treeCensus.totalSpecies,
  unidentified: treeCensus.unidentified,
  totalCo2eKg: treeCensus.totalCo2eKg,
  carbonKg: treeCensus.carbonKg,
  agbKg: treeCensus.agbKg,
  shannon: treeCensus.shannon,
  simpson: treeCensus.simpson,
  surveyFrom: treeCensus.surveyFrom,
  surveyTo: treeCensus.surveyTo,
  sandalwood,
  nativeCount,
  exoticCount,
  unclassifiedCount,
  nativePct: (nativeCount / totalCounted) * 100,
  exoticPct: (exoticCount / totalCounted) * 100,
  unclassifiedPct: (unclassifiedCount / totalCounted) * 100,
}

export const maxSpeciesCount = Math.max(...species.map((s) => s.count))
